`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// input_1_datapath: board top level around input_1_datapath_core -- auto-generated by datapath_gen.py
//
//   start        button: run the computation (inputs are latched on the press)
//   step_switch  0 = run at full speed
//                1 = single-step: the start press executes cycle 1 (IDLE -> step 1,
//                    latching the inputs); each `step` press then executes exactly
//                    ONE more clock cycle of the whole datapath (FSM, registers and
//                    unit pipelines advance together), however long it is held
//   function_probe_sel  selects which unit output is shown on the leftmost digit: 0=add0, 1=mul0, 2=sub0
//   display      digits 3..0 (left to right) = Q, Z, Y, X; leftmost digit = unit probe
//   busy LED     computation in progress   done LED  results valid (stays lit)
//   switches     in_A=sw[3:0], in_C=sw[7:4], in_B=sw[11:8], function_probe_sel=sw[14:13], step_switch=sw[15]
// ---------------------------------------------------------------------------
module input_1_datapath #(
    parameter WIDTH = 4,
    parameter DEBOUNCE_CYCLES = 32'd1_000_000     // ~10 ms at 100 MHz
)(
    input  wire             clk,
    input  wire             rst,
    input  wire             start,
    input  wire             step,
    input  wire             step_switch,
    input  wire [WIDTH-1:0] in_A,
    input  wire [WIDTH-1:0] in_C,
    input  wire [WIDTH-1:0] in_B,
    output wire [7:0]       an,
    output wire [6:0]       cn,
    output wire             busy,
    output wire             done,
    input  wire [1:0]       function_probe_sel
);

    // ---- 2-FF synchronizers: buttons and the mode switch are asynchronous to clk
    reg [1:0] start_sync, step_sync, mode_sync;
    always @(posedge clk) begin
        start_sync <= {start_sync[0], start};
        step_sync  <= {step_sync[0],  step};
        mode_sync  <= {mode_sync[0],  step_switch};
    end
    wire step_mode = mode_sync[1];

    // ---- debounce, then turn each press into a ONE-cycle pulse
    wire start_db, step_db;
    debouncer #(.COUNT(DEBOUNCE_CYCLES)) u_start_db (
        .clk(clk), .rst(rst), .button(start_sync[1]), .debounced_button(start_db));
    debouncer #(.COUNT(DEBOUNCE_CYCLES)) u_step_db (
        .clk(clk), .rst(rst), .button(step_sync[1]),  .debounced_button(step_db));
    reg start_db_q, step_db_q;
    always @(posedge clk) begin
        if (rst) begin start_db_q <= 1'b0; step_db_q <= 1'b0; end
        else     begin start_db_q <= start_db; step_db_q <= step_db; end
    end
    wire start_pulse = start_db & ~start_db_q;
    wire step_pulse  = step_db  & ~step_db_q;

    // ---- clock enable for the whole datapath
    wire core_busy, core_done;
    wire start_go = start_pulse & ~core_busy;          // accepted start
    wire ce = ~step_mode | step_pulse | start_go;

    wire [WIDTH-1:0] out_Q;
    wire [WIDTH-1:0] out_Z;
    wire [WIDTH-1:0] out_Y;
    wire [WIDTH-1:0] out_X;
    wire [WIDTH-1:0] dbg_add0_out;
    wire [WIDTH-1:0] dbg_mul0_out;
    wire [WIDTH-1:0] dbg_sub0_out;
    wire [3:0] dbg_state;
    input_1_datapath_core #(.WIDTH(WIDTH)) u_core (
        .clk(clk),
        .rst(rst),
        .ce(ce),
        .start(start_go),
        .in_A(in_A),
        .in_C(in_C),
        .in_B(in_B),
        .out_Q(out_Q),
        .out_Z(out_Z),
        .out_Y(out_Y),
        .out_X(out_X),
        .dbg_add0_out(dbg_add0_out),
        .dbg_mul0_out(dbg_mul0_out),
        .dbg_sub0_out(dbg_sub0_out),
        .dbg_state(dbg_state),
        .busy(core_busy),
        .done(core_done)
    );

    // ---- status LEDs: `done` stays lit until the next accepted start
    reg done_led;
    always @(posedge clk) begin
        if (rst || start_go)  done_led <= 1'b0;
        else if (core_done)   done_led <= 1'b1;
    end
    assign busy = core_busy;
    assign done = done_led;

    // ---- unit probe for the leftmost digit
    reg [WIDTH-1:0] function_probe;
    always @(*) begin
        case (function_probe_sel)
            2'd0: function_probe = dbg_add0_out;
            2'd1: function_probe = dbg_mul0_out;
            2'd2: function_probe = dbg_sub0_out;
            default: function_probe = dbg_sub0_out;
        endcase
    end

    seven_seg u_display (
        .clk(clk), .rst(rst),
        .digit3(out_Q[3:0]), .digit2(out_Z[3:0]), .digit1(out_Y[3:0]), .digit0(out_X[3:0]),
        .digit_function(function_probe[3:0]),
        .an(an), .seg(cn));

endmodule
